-- Rebuild Medina Book 3 rules from Sharkh_Medinskiy_3.doc/PDF as readable cards.
-- Scope: only Мединский курс (Том 3) rules. Words and other volumes are untouched.
begin;

delete from public.rule_sections where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)');
delete from public.rules where course_name = 'Мединский курс (Том 3)';

insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary) values
('Мединский курс (Том 3)', '1', 'الإِعْرَابُ وَالْبِنَاءُ فِي الأَسْمَاءِ (изменяемость и неизменяемость имён)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الإِعْرَابُ وَالْبِنَاءُ فِي الأَسْمَاءِ</span><p class="rule-study-text">изменяемость и неизменяемость имён. Шарх различает مُعْرَب и مَبْنِيّ: у первого конец меняется из-за عامل, у второго форма остаётся одной.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الإِعْرَابُ وَالْبِنَاءُ فِي الأَسْمَاءِ</span><span class="rule-term-ru">الإِعْرَابُ وَالْبِنَاءُ فِي الأَسْمَاءِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">إِعْرَابٌ</span><span class="rule-term-ru">изменение окончания слова по его роли в предложении</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">بِنَاءٌ</span><span class="rule-term-ru">неизменность окончания; слово сохраняет одну форму</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مُعْرَبٌ</span><span class="rule-term-ru">изменяемое слово: آخره يتغيّر بسبب العامل</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово: آخره لا يتغيّر بسبب العامل</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">عَامِلٌ</span><span class="rule-term-ru">управляющий фактор, из-за которого меняется إِعْرَاب</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный падеж</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный падеж</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مَجْرُورٌ</span><span class="rule-term-ru">в состоянии جرّ / родительный падеж после предлога или идафы</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">الضَّمَّةُ</span><span class="rule-term-ru">дамма; основной признак رفع</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">الْفَتْحَةُ</span><span class="rule-term-ru">фатха; основной признак نصب</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">الْكَسْرَةُ</span><span class="rule-term-ru">касра; основной признак جرّ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала определите: это اِسْمٌ، فِعْلٌ или حَرْفٌ.</li><li>Найдите عامل и роль слова: مُبْتَدَأ، خَبَر، فَاعِل، مَفْعُولٌ بِهِ или другое место.</li><li>После этого проверьте признак: رَفْع، نَصْب، جَرّ или جَزْم и сравните с примерами шарха.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">( أ ) في الأسماءِ :</span><span class="rule-example-ru">Пример/разбор сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">الاسمُ إِمَّا مُعْرَبٌ وإِما مَبْنِيٌّ .</span><span class="rule-example-ru">Пример/разбор сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">فالْمُعْرَبُ ، هو : ما تَغَيَّرَ آخِرُهُ بسبب العامل ، نحو :</span><span class="rule-example-ru">Пример/разбор сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">جاءَ الْمُدَرِّسُ . المدرسُ : فاعل مرفوع وعلامة رفعه الضَّمَّة .</span><span class="rule-example-ru">Пример/разбор сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">سألت المدرسَ . المدرسَ : مفعول به منصوب وعلامة نصبه الفتحة .</span><span class="rule-example-ru">Пример/разбор сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الإِعْرَابُ وَالْبِنَـاءُ</div><div class="rule-source-line">( أ ) في الأسماءِ :</div><div class="rule-source-line">الاسمُ إِمَّا مُعْرَبٌ وإِما مَبْنِيٌّ .</div><div class="rule-source-line">فالْمُعْرَبُ ، هو : ما تَغَيَّرَ آخِرُهُ بسبب العامل ، نحو :</div><div class="rule-source-line">جاءَ الْمُدَرِّسُ . المدرسُ : فاعل مرفوع وعلامة رفعه الضَّمَّة .</div><div class="rule-source-line">سألت المدرسَ . المدرسَ : مفعول به منصوب وعلامة نصبه الفتحة .</div><div class="rule-source-line">سلّمت على المدرسِ . المدرسِ : اسم مجرور وعَلامة جرَّه الكسرة .</div><div class="rule-source-line">فالتَّغَيُّرُ الذي حَدَثَ في آخر كلمة ( المدرس ) الضمة ، ثم الفتحة ، ثم الكسرة ، هذا التَّغَيُّرُ يدلّ على أن كلمة المدرس مُعْرَبَة ؛ لأن آخرها تغيَّر بسبب العامل ، وهو الفعل وحرف الجر.</div><div class="rule-source-line">والْمَبْنِيُّ ، هو : ما لا يَتَغَيَّرُ آخرُه بسببِ العَامِلِ ، أي : يَلْزَمُ حالةً واحدةً ، نحو :</div><div class="rule-source-line">جاء هؤلاءِ . هؤلاءِ : في محل رفع فاعل مبنيّ على الكسر .</div><div class="rule-source-line">رأيت هؤلاءِ . هؤلاءِ : في محل نصب مفعول به مبنيّ على الكسر .</div><div class="rule-source-line">سلّمت على هؤلاءِ . هؤلاءِ : في محل جر مبنيّ على الكسر .</div><div class="rule-source-line">فكلمة هؤلاء كما ترى لم يتَغيَّر آخرها مع أنّ العاملَ قد تغيَّر ، فهي إذا كلمة مَبْنِيَّة ؛ لأنَّ آخرها لم يتغيَّر مع تغيُّر العامل .</div><div class="rule-source-line">* نَلْحَظُ مِمَّا سَبَقَ : أنّ الاسم المعرب، نقول في إعرابه: مرفوع ، أو منصوب، أو مجرور.</div><div class="rule-source-line">أَمَّا الاسمُ المبنيّ ، فنقول في إعرابه : في محل رفع ، أو في محل نصب ، أو في محل جرّ .</div><div class="rule-source-line">المعربُ والمبنيُّ من الأسماءِ</div></div></div><div class="rule-check-card"><b>Проверка:</b> сверяйте роль слова, عامل и конечный признак. Если слово مبنيّ, говорите «في محل رفع/نصب/جر», а если معرب — «مرفوع/منصوب/مجرور/مجزوم».</div></div>', 1, 'rule', 'Шарх различает مُعْرَب и مَبْنِيّ: у первого конец меняется из-за عامل, у второго форма остаётся одной.'),
('Мединский курс (Том 3)', '1', 'الْمُعْرَبُ وَالْمَبْنِيُّ مِنَ الأَسْمَاءِ (какие имена изменяемые, а какие неизменяемые)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمُعْرَبُ وَالْمَبْنِيُّ مِنَ الأَسْمَاءِ</span><p class="rule-study-text">какие имена изменяемые, а какие неизменяемые. Все имена в основе مُعْرَب, кроме групп: местоимений, указательных, относительных, вопросительных, условных имён, некоторых ظروف, составных чисел и أسماء الأفعال.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُعْرَبُ وَالْمَبْنِيُّ مِنَ الأَسْمَاءِ</span><span class="rule-term-ru">الْمُعْرَبُ وَالْمَبْنِيُّ مِنَ الأَسْمَاءِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">إِعْرَابٌ</span><span class="rule-term-ru">изменение окончания слова по его роли в предложении</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مُعْرَبٌ</span><span class="rule-term-ru">изменяемое слово: آخره يتغيّر بسبب العامل</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово: آخره لا يتغيّر بسبب العامل</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الضَّمَائِرُ</span><span class="rule-term-ru">местоимения</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">حَالٌ</span><span class="rule-term-ru">обстоятельство состояния; обычно منصوب</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُثَنَّى</span><span class="rule-term-ru">двойственное число</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَمْ</span><span class="rule-term-ru">частица отрицания прошлого смысла; делает المضارع مجزوم</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَمَّا</span><span class="rule-term-ru">частица отрицания «ещё не»; делает المضارع مجزوم</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ابْنٌ</span><span class="rule-term-ru">слово «сын»; его хамза иногда удаляется на письме</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала определите: это اِسْمٌ، فِعْلٌ или حَرْفٌ.</li><li>Найдите عامل и роль слова: مُبْتَدَأ، خَبَر، فَاعِل، مَفْعُولٌ بِهِ или другое место.</li><li>После этого проверьте признак: رَفْع، نَصْب، جَرّ или جَزْم и сравните с примерами шарха.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">الأسماءُ كلُّها معربةٌ ما عدا الفِئَاتِ الآتيةِ :</span><span class="rule-example-ru">Пример/разбор сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">ضمائرُ نصبٍ ، أم ضمائرُ جرٍّ .</span><span class="rule-example-ru">Пример/разбор сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">* جدولٌ يُبَيَّنُ الضَّمائرَ الْمُتَّصِلَةَ :</span><span class="rule-example-ru">Пример/разбор сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">| لي . كتابي</span><span class="rule-example-ru">Пример/разбор сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">| لك . كتابك</span><span class="rule-example-ru">Пример/разбор сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الأسماءُ كلُّها معربةٌ ما عدا الفِئَاتِ الآتيةِ :</div><div class="rule-source-line">1- الضَّمَائِرُ ، سواء أكانت ضمائرُ مُتَّصِلَةً ، أم مُنْفَصِلَةً ، وسواء أكانت ضمائرُ رفعٍ ، أم</div><div class="rule-source-line">ضمائرُ نصبٍ ، أم ضمائرُ جرٍّ .</div><div class="rule-source-line">* جدولٌ يُبَيَّنُ الضَّمائرَ الْمُتَّصِلَةَ :</div><div class="rule-source-line">ضمائر الرفع</div><div class="rule-source-line">| المثال</div><div class="rule-source-line">| ضمائر النصب</div><div class="rule-source-line">| المثال</div><div class="rule-source-line">| ضمائر الجر</div><div class="rule-source-line">| المثال</div><div class="rule-source-line">|</div><div class="rule-source-line">| التَّاء المتحرَّكة</div><div class="rule-source-line">| ذَهَبْتَُِ</div><div class="rule-source-line">| ياء الْمُتكلَّم</div><div class="rule-source-line">| سألني</div><div class="rule-source-line">| ياء المتكلَّم</div><div class="rule-source-line">| لي . كتابي</div><div class="rule-source-line">|</div><div class="rule-source-line">| واو الجماعة</div><div class="rule-source-line">| ذَهَبُوا</div><div class="rule-source-line">| كاف الْمُخاطَب</div><div class="rule-source-line">| سألكَِ</div><div class="rule-source-line">| كاف المخاطَب</div><div class="rule-source-line">| لك . كتابك</div><div class="rule-source-line">|</div><div class="rule-source-line">| ياء المخاطبة</div><div class="rule-source-line">| تذهبينَ</div><div class="rule-source-line">| هاء الغائب</div><div class="rule-source-line">| سَأَلَهُ سَأَلَهَا</di